&lt;span class=&quot;Cat&#233;gorie&quot;&gt;&lt;b&gt;Cat&#233;gorie&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Trousses-D&#233;quipement.html&quot; title=&quot;Trousses d&amp;#39;&#233;quipement&quot;&gt;Trousses d&#39;&#233;quipement&lt;/a&gt;&lt;/span&gt;
&lt;hr&gt;
Cette trousse comprend un &lt;a class=&quot;pagelink&quot; href=&quot;Sac-&#192;-Dos-(Objet).html&quot; title=&quot;Sac &#224; dos&quot;&gt;sac &#224; dos&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Sac-De-Couchage-(Objet).html&quot; title=&quot;Sac de couchage&quot;&gt;sac de couchage&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;Bourse-(Objet).html&quot; title=&quot;Bourse&quot;&gt;bourse&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;Chope-(Objet).html&quot; title=&quot;Chope&quot;&gt;chope en terre cuite&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;Dague-(Arme).html&quot; title=&quot;Dague&quot;&gt;dague&lt;/a&gt;, deux &lt;a class=&quot;pagelink&quot; href=&quot;Hame&#231;on-(Objet).html&quot; title=&quot;Hame&#231;on&quot;&gt;hame&#231;ons&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Silex-Et-Amorce-(Objet).html&quot; title=&quot;Silex et amorce&quot;&gt;silex et une amorce&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;Aiguille-&#192;-Coudre-(Objet).html&quot; title=&quot;Aiguille &#224; coudre&quot;&gt;aiguille &#224; coudre&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Sifflet-(Objet).html&quot; title=&quot;Sifflet&quot;&gt;sifflet&lt;/a&gt;, 15 m&#232;tres de &lt;a class=&quot;pagelink&quot; href=&quot;Ficelle-(Objet).html&quot; title=&quot;Ficelle (15 m)&quot;&gt;ficelle&lt;/a&gt;, 15 m&#232;tres de fil &#224; coudre, une semaine de &lt;a class=&quot;pagelink&quot; href=&quot;Rations-De-Survie-(Objet).html&quot; title=&quot;Rations de survie&quot;&gt;rations de survie&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;Outre-(Objet).html&quot; title=&quot;Outre&quot;&gt;outre&lt;/a&gt; et une &lt;a class=&quot;pagelink&quot; href=&quot;Pierre-&#192;-Aiguiser-(Objet).html&quot; title=&quot;Pierre &#224; aiguiser&quot;&gt;pierre &#224; aiguiser&lt;/a&gt;. Les trousses destin&#233;es aux cr&#233;atures de taille P p&#232;sent 3,75 kilos. Si le sac de couchage et les rations restent au camp ou sur une monture, la trousse p&#232;se 6 kilos de moins pour les cr&#233;atures de taille M et 1,5 kilos de moins pour les cr&#233;atures de taille P.
